insert into research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data) values
  ('冷泉能控', '—', 'ai', 'hw', false, '天使轮', null, null, null, '2026-10', '{"seg": "hw", "code": "—", "desc": "深圳两相液冷企业，面向 AI 芯片与智算中心做系统级热管理，产品覆盖冷板、CDU、管路与整机柜方案，创始团队 2020 年起研发、2025 年 3 月成立公司。", "name": "冷泉能控", "note": "冷泉的散热对象是 AI 芯片与智算中心，不是晶圆制造设备，故归 ai/hw；若后续建「算力基础设施」环节可迁移。", "tech": [{"date": "2026-10", "desc": "万朗磁塑、共青城金盛溪四期跟投，两家 A 股上市公司战略入股；资金用于扩团队、研发与供应链", "kind": "融资", "title": "完成数千万元天使轮，震安科技领投"}, {"date": "2026-01", "desc": "国内首家由产业方联合发布两相液冷服务器，已取得产品兼容性认证", "kind": "产品发布", "title": "与软通动力、软通华方联合发布两款两相液冷服务器"}, {"date": "2025-03", "desc": "总部深圳南山；团队 2024 年初完成首代样机，2025 年初实现首代商用量产", "kind": "公司成立", "title": "冷泉能控科技（深圳）有限公司成立"}], "round": "天使轮", "spark": [], "listed": false, "funding": [{"inv": "震安科技（领投）、万朗磁塑、共青城金盛溪四期", "date": "2026-10", "round": "天使轮", "amount": "数千万元"}], "industry": "ai", "valuation": null, "executives": [{"bio": "中国人民大学硕士，国内首批液氮服务器极客、近 10 年超频经验；曾任某手术机器人公司联合创始人/CPO，主导 −196℃深冷+85℃热击冷热复合肿瘤消融设备", "name": "何民威", "role": "management", "title": "创始人"}, {"bio": "国家优青、全球高被引学者，师从何雅玲院士", "name": "李庆", "role": "other", "title": "首席科学家"}, {"bio": "西安交通大学本硕博，华为天才少年候选人，前 985 高校教授；泵驱无水常压两相液冷技术提出者", "name": "刘博", "role": "management", "title": "CTO"}], "latestTech": "常压无水两相液冷：单板最高 4400W、热流密度 300W/cm²、最低热阻 0.011℃/W，PUE 实测 1.08–1.12", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "天使轮：震安科技（领投）、万朗磁塑、共青城金盛溪四期", "investorsStructured": [{"date": "2026-10", "kind": "cvc", "name": "震安科技", "note": "减震龙头，A 股上市，战略入股", "role": "lead", "round": "天使轮"}, {"date": "2026-10", "kind": "cvc", "name": "万朗磁塑", "note": "A 股上市公司，磁性材料", "role": "other", "round": "天使轮"}, {"date": "2026-10", "kind": "gov", "name": "共青城金盛溪四期", "note": "江西省金控旗下基金", "role": "other", "round": "天使轮"}]}'::jsonb),
  ('格物通智', '—', 'ai', 'llm', false, '天使轮', null, null, null, '2026-10', '{"seg": "llm", "code": "—", "desc": "杭州具身大脑公司，构建「物理反演世界模型 + PSI 物理自进化」技术体系，面向真实产业场景做自进化灵巧操作智能；2026 年 8 月成立，两个月内完成近亿元天使轮。", "name": "格物通智", "note": "与幂级智能同属「世界模型」细分，但路线不同：幂级主打 Next State Prediction 订阅制，格物通智主打物理反演 + 自进化灵巧操作。", "tech": [{"date": "2026-10", "desc": "匹克投资、鸿富资产、杭州资本、杭州人才集团、某省级具身产投及多家头部上市公司；资金用于世界模型大规模预训练与硬件本体构建", "kind": "融资", "title": "完成近亿元天使轮"}, {"date": "2026-08", "desc": "创始人兼 CEO 蔡佳，曾任职华为 2012 实验室及车 BU 2030 实验室", "kind": "公司成立", "title": "格物通智成立于杭州"}], "round": "天使轮", "spark": [], "listed": false, "funding": [{"inv": "匹克投资、鸿富资产、杭州资本、杭州人才集团、某省级具身产投、多家头部上市公司", "date": "2026-10", "round": "天使轮", "amount": "近亿元"}], "industry": "ai", "valuation": null, "executives": [{"bio": "博士，曾任职华为 2012 实验室及车 BU 2030 实验室，参与 ADS 2.0 至 4.0 核心技术研发", "name": "蔡佳", "role": "management", "title": "创始人、CEO"}], "latestTech": "物理反演世界模型 + PSI 物理自进化，主攻灵巧操作；创始人蔡佳参与华为 ADS 2.0–4.0 核心技术研发", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "天使轮：匹克投资、鸿富资产、杭州资本、杭州人才集团、某省级具身产投、多家头部上市公司", "investorsStructured": [{"date": "2026-10", "kind": "vc", "name": "匹克投资", "role": "other", "round": "天使轮"}, {"date": "2026-10", "kind": "gov", "name": "杭州资本", "note": "杭州国资", "role": "other", "round": "天使轮"}, {"date": "2026-10", "kind": "gov", "name": "杭州人才集团", "role": "other", "round": "天使轮"}]}'::jsonb),
  ('华瑞指数云', '—', 'ai', 'hw', false, '未披露', null, null, null, '2026-10', '{"seg": "hw", "code": "—", "desc": "深圳 AI 原生数据基础设施公司（ExponTech），以自研分布式存储引擎 WiDE 与 KV 元数据引擎「天枢」构建 WADP 统一存储底座，2026 年主推 AI 推理 KV Cache 存储系统 WQS。", "name": "华瑞指数云", "note": "公司自述为「AI 原生数据基础设施」，不是芯片公司；归 ai/hw（算力基础设施）而非 semiconductor。", "tech": [{"date": "2026-10", "desc": "产业基金与琮碧秋实联合领投，某国有产投跟投；资金投向 WQS 研发与规模化交付", "kind": "融资", "title": "完成新一轮超亿元融资"}, {"date": "2026", "desc": "同时推进金融、自动驾驶、半导体等行业客户；WADP 已在 200 余家客户核心生产环境运行", "kind": "产品进展", "title": "WQS 进入头部大模型厂商生产级 POC"}, {"date": "2020-01", "desc": "总部深圳南山，核心团队来自华为、腾讯、IBM、微软、EMC", "kind": "公司成立", "title": "华瑞指数云科技（深圳）有限公司成立"}], "round": "未披露", "spark": [], "listed": false, "funding": [{"inv": "产业基金、琮碧秋实（联合领投）、某国有产投基金", "date": "2026-10", "round": "新一轮", "amount": "超亿元"}, {"inv": "卓源亚洲、同创伟业、明势资本、阿米巴资本", "date": "2025-01", "round": "A轮", "amount": "约亿元"}, {"inv": "明势资本（领投）", "date": "2023-03", "round": "Pre-A轮", "amount": "亿元级"}], "industry": "ai", "valuation": null, "executives": [{"bio": "曾任华为云计算产品线 COO", "name": "靳广亮", "role": "management", "title": "创始人、CEO"}, {"bio": "博士，前华为云与计算 BG 西欧区 CTO、华为公有云创始核心专家；提出 SDS 2.0", "name": "曹羽中", "role": "management", "title": "联合创始人、CTO"}], "latestTech": "WQS 围绕 KV Cache 的复用、共享与调度重构「存储—GPU」IO 路径，目标在不增 GPU 的前提下提升 Token 产出", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "新一轮：产业基金、琮碧秋实（联合领投）、某国有产投基金", "investorsStructured": [{"date": "2026-10", "kind": "vc", "name": "琮碧秋实", "role": "lead", "round": "新一轮"}, {"date": "2025-01", "kind": "vc", "name": "卓源亚洲", "role": "other", "round": "A轮"}, {"date": "2023-03", "kind": "vc", "name": "明势资本", "role": "lead", "round": "Pre-A轮"}]}'::jsonb),
  ('粒曼生物', '—', 'ai', 'ai-med', false, '天使轮', null, null, null, '2026-10', '{"seg": "ai-med", "code": "—", "desc": "杭州 AI 虚拟细胞（AIVC）上游数据基础设施，用高通量细胞编辑平台批量生产扰动样本，解决 AI 制药的「数据饥荒」；2024 年成立。", "name": "粒曼生物", "note": "AI for Science 方向，归 ai/ai-med；与机器人、半导体无直接产业链关系。", "tech": [{"date": "2026-10", "desc": "上海弘晖领投，兴华鼎立、杭州润苗基金跟投", "kind": "融资", "title": "完成数千万元天使轮"}, {"date": "2024", "desc": "定位人工智能虚拟细胞产业上游的数据基础设施供应商", "kind": "公司成立", "title": "粒曼生物成立于杭州"}], "round": "天使轮", "spark": [], "listed": false, "funding": [{"inv": "上海弘晖（领投）、兴华鼎立、杭州润苗基金", "date": "2026-10", "round": "天使轮", "amount": "数千万元"}], "industry": "ai", "valuation": null, "executives": [], "latestTech": "高通量细胞编辑 + 扰动数据生产，把细胞实验从「手工活」变「流水线」，单批可做数千个扰动", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "天使轮：上海弘晖（领投）、兴华鼎立、杭州润苗基金", "investorsStructured": [{"date": "2026-10", "kind": "vc", "name": "上海弘晖", "role": "lead", "round": "天使轮"}, {"date": "2026-10", "kind": "vc", "name": "兴华鼎立", "role": "other", "round": "天使轮"}]}'::jsonb),
  ('海博特', '—', 'ai', 'ai-med', false, 'B+轮', null, null, null, '2026-10', '{"seg": "ai-med", "code": "—", "desc": "广州临床 CRO，特色是中医药上市后再评价与真实世界研究，自研 MedioSuite 数智化平台（13 款工具），2026 年推出 AI 辅助方案设计与入组评估工具。", "name": "海博特", "note": "严格说是「AI 赋能的 CRO」，不是纯 AI 公司；收入来自临床服务而非软件。", "tech": [{"date": "2026-10", "desc": "远翼投资领投，广州健康产投、万联广生、荔湾广药基金、鲸犀投资参与；五年内第五轮", "kind": "融资", "title": "完成 7,006 万元 B+ 轮"}, {"date": "2026", "desc": "从执行层数字化延伸到临床研究前端的决策赋能", "kind": "产品发布", "title": "推出 MedioSeek 与 MedioCompose"}], "round": "B+轮", "spark": [], "listed": false, "funding": [{"inv": "远翼投资（领投）、广州健康产投、万联广生、荔湾广药基金、鲸犀投资", "date": "2026-10", "round": "B+轮", "amount": "7,006 万元"}], "industry": "ai", "valuation": null, "executives": [{"bio": "中医药学专业，深耕 CRO 市场 14 年，2026 年考取南方医科大学公共卫生政策与管理博士", "name": "王帅帅", "role": "management", "title": "创始人"}], "latestTech": "MedioSeek + MedioCompose：用多智能体辅助医学方案设计、法规校验与证据追溯；平台已服务超 1000 个临床试验项目", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "B+轮：远翼投资（领投）、广州健康产投、万联广生、荔湾广药基金、鲸犀投资", "investorsStructured": [{"date": "2026-10", "kind": "pe", "name": "远翼投资", "note": "远东宏信集团旗下", "role": "lead", "round": "B+轮"}, {"date": "2026-10", "kind": "gov", "name": "广州健康产投", "role": "other", "round": "B+轮"}, {"date": "2026-10", "kind": "cvc", "name": "广药资本", "role": "other", "round": "B+轮"}]}'::jsonb),
  ('法奥机器人', '—', 'robotics', 'industrial', false, 'D轮', null, null, null, '2026-10', '{"seg": "industrial", "code": "—", "desc": "苏州协作机器人厂商，控制器、编码器、伺服驱动器、谐波减速机等核心零部件自研自产；FR 系列 11 款（3–35kg），2026 年全球首发 ART 工业级人形力控臂。", "name": "法奥机器人", "note": "核心零部件自研率高（控制器/编码器/伺服/谐波减速机），是协作机器人里少数做全链的；ART 力控臂让其进入人形供应链。", "tech": [{"date": "2026-10", "desc": "美团龙珠、美团分别领投；资金用于核心零部件产能固投与工业具身智能扩产", "kind": "融资", "title": "连续完成 C+、D 轮，累计近 10 亿元"}, {"date": "2026", "desc": "GGII 口径；2026 年预计全球订单 1.8 万台、同比 +68%，海外销售网点 50+", "kind": "市场地位", "title": "2025 年中国协作机器人销量与海外出货双第一"}, {"date": "2026", "desc": "从定制化人形力控臂服务走向通用化、标准化、模块化", "kind": "产品发布", "title": "ART 工业级人形力控臂"}], "round": "D轮", "spark": [], "listed": false, "funding": [{"inv": "美团龙珠、美团（分别领投）、永鑫方舟、狮山二期、苏创投、国联民生资本、苏产投、清流资本", "date": "2026-10", "round": "C+轮/D轮", "amount": "近 10 亿元（两轮累计）"}], "industry": "robotics", "valuation": null, "executives": [{"bio": "哈工大背景，曾供职于工业机器人企业 ABB", "name": "姚庭", "role": "management", "title": "创始人"}], "latestTech": "ART 系列工业人形力控臂全球首发；已与博银合创、杰克科技签署共 4,000 台战略合作协议", "execChanges": [], "lastFunding": "2026-10", "latestFunding": "C+轮/D轮：美团龙珠、美团（分别领投）、永鑫方舟、狮山二期、苏创投、国联民生资本、苏产投、清流资本", "investorsStructured": [{"date": "2026-10", "kind": "cvc", "name": "美团", "note": "本地生活场景 + 工业具身智能的战略协同", "role": "lead", "round": "D轮"}, {"date": "2026-10", "kind": "cvc", "name": "美团龙珠", "role": "lead", "round": "C+轮"}, {"date": "2026-10", "kind": "gov", "name": "苏创投", "role": "other", "round": "C+轮/D轮"}, {"date": "2026-10", "kind": "vc", "name": "清流资本", "role": "other", "round": "C+轮/D轮"}]}'::jsonb),
